//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn only_transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between attempts, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay before the retry after `failed_attempt`.
    ///
    /// `failed_attempt` is one for the first failed call. Saturating arithmetic
    /// keeps large attempt counts from overflowing before the cap is applied.
    pub fn delay_for_retry(&self, failed_attempt: u32) -> u64 {
        let exponent = failed_attempt.saturating_sub(1);
        let delay = if exponent >= u64::BITS {
            u64::MAX
        } else {
            let shift = exponent as u32;
            if self.base_delay_ms > (u64::MAX >> shift) {
                u64::MAX
            } else {
                self.base_delay_ms << shift
            }
        };
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_growth_saturates_at_the_configured_cap() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };

        assert_eq!(config.delay_for_retry(1), 10);
        assert_eq!(config.delay_for_retry(2), 20);
        assert_eq!(config.delay_for_retry(3), 25);
        assert_eq!(config.delay_for_retry(u32::MAX), 25);
    }

    #[test]
    fn overflowing_growth_saturates_before_applying_the_cap() {
        let config = RetryConfig {
            max_attempts: 3,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(1), u64::MAX);
        assert_eq!(config.delay_for_retry(2), u64::MAX);
    }

    #[test]
    fn zero_base_delay_stays_zero() {
        let config = RetryConfig {
            max_attempts: 2,
            base_delay_ms: 0,
            max_delay_ms: 100,
        };

        assert_eq!(config.delay_for_retry(1), 0);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 1;

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
                attempt += 1;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_and_returns_on_success() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            attempts += 1;
            if attempts < 3 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(attempts, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_do_not_retry() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            attempts += 1;
            Err(RetryError::Permanent("invalid input".into()))
        });
        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(attempts, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_the_initial_call() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(3), &mut sleeper, || {
            attempts += 1;
            Err(RetryError::Transient("temporary".into()))
        });
        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(attempts, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_with_bounded_delays() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 7,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 | 2 | 3 => Err(RetryError::Transient("temporary outage".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 4);
    assert_eq!(sleeper.sleeps, vec![7, 14, 20]);
}

#[test]
fn public_api_stops_at_attempt_budget() {
    let config = RetryConfig {
        max_attempts: 2,
        base_delay_ms: 1,
        max_delay_ms: 1,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(
        result,
        Err(RetryError::Transient("still unavailable".into()))
    );
    assert_eq!(attempts, 2);
    assert_eq!(sleeper.sleeps, vec![1]);
}

#[test]
fn public_delay_calculation_saturates_for_extreme_attempts() {
    let config = RetryConfig {
        max_attempts: u32::MAX,
        base_delay_ms: u64::MAX,
        max_delay_ms: 123,
    };

    assert_eq!(config.delay_for_retry(u32::MAX), 123);
}
